import{_ as i,l,o as t,c as s,v as e,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"wait-for 图","description":"","frontmatter":{"title":"wait-for 图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wait-for-graph.md","filePath":"cs/wait-for-graph.md","lastUpdated":1789023840000}'),h={name:"cs/wait-for-graph.md"};function _(f,a,T,u,E,m){const o=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="wait-for-图" tabindex="-1">wait-for 图 <a class="header-anchor" href="#wait-for-图" aria-label="Permalink to &quot;wait-for 图&quot;">​</a></h1><div class="epigraph"><p>边 $T_i \\to T_j$ 表示 $i$ 等 $j$ 的锁；环即死锁。检测是图上的环，牺牲者是策略，不是代数。</p><footer>—— 据 Gray and Reuter；Holt 死锁检测；主干库内死锁课的图论补全</footer></div><p><a href="/cs/gap-locks-predicate">上一课</a>让间隙也进入等待。本课不定义 next-key。缺口是死锁：主干 <a href="/cs/db-deadlock">库内死锁</a> 与 wait-die 预防。进阶钉 wait-for 图（WFG）：节点事务，边等待。有向环当且仅当死锁（在单资源类型、互斥、不可抢占模型下）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预防（wait-die、wound-wait）按时间戳打破环，可能误杀。检测：等图变化或周期 DFS/拓扑。缺口是<strong>何时跑检测</strong>：每次加锁失败入队都 DFS，精确但贵；周期检测有延迟。分布式后课：全局图或探针。</p><p>牺牲者：选回滚代价小的（年轻、写集小）。回滚到保存点还是整事务，产品不同。间隙锁、意向锁都是图上的节点持有。</p><p><span class="marginnote">Holt 的死锁模型。Gray and Reuter 事务处理专章。latch 死锁不进 WFG，靠顺序避免——pin-latch 课。本课事务锁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>锁管理器：等待队列。边动态加删。检测：从新等待者反向或正向找环。超时：不建图，等超时 abort——假阳性（负载高）与假阴性（超时太长）都有。</p><p>与 OCC：等待少，环少，abort 来自验证不是 WFG。混合系统两套失败模式。</p>',10)),(t(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22T1%20%E7%AD%89%E8%A1%8C%20A%22%5D%20--%3E%20T2%5B%22T2%20%E6%8C%81%E6%9C%89%20A%22%5D%0A%20%20T2%20--%3E%20T3%5B%22T2%20%E7%AD%89%E8%A1%8C%20B%22%5D%0A%20%20T3%20--%3E%20T1%5B%22T3%20%E7%AD%89%20T1%20%E7%9A%84%E9%94%81%22%5D%0A%20%20CY%5B%22%E7%8E%AF%22%5D%20--%3E%20VIC%5B%22%E9%80%89%E7%89%BA%E7%89%B2%E8%80%85%E5%9B%9E%E6%BB%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>严格 2PL 持锁到提交，环一旦成要等到检测。锁升级瞬间抓表锁，容易与行锁持有者成环。计划导致锁顺序：两语句反序更新两行是应用级死锁，WFG 照样检出。</p><p>日志：死锁事件应含等待图快照，否则无法修应用顺序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 MVCC 版本链回收。也不把死锁当网络分区。Calvin 确定性调度可避免锁死锁，后课。</p><p>后课默认：悲观锁用 WFG 或超时；预防用戳。MVCC GC：版本回收与快照最小戳，另一类「等待」——等读者结束。</p><p>死锁是等待环，不是慢查询。诊断先看锁图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>wait-for 有向环即死锁；检测或超时或预防。</li><li>间隙与意向都进图；latch 不进。</li><li>MVCC 版本回收下一课。</li><li>出处：Gray and Reuter；Holt；wait-die 对照。</li></ul>',9))])}const w=i(h,[["render",_]]);export{C as __pageData,w as default};
